# Let me look for common patterns and potential replacements
inputs = ['euj', 'hcukcf', 'gudh', 'jbvi', 'axbvak']
outputs = ['egffdhz', 'hcgffkcf', 'ggffdh', 'dhzxggffvi', 'axxggffvak']

# Looking for patterns in character substitutions
print("Analyzing character substitutions:")
print("=" * 40)

# Check which characters appear in inputs but not in outputs (additions)
# and which characters in outputs are new
for i in range(len(inputs)):
    print(f"Input: '{inputs[i]}' -> Output: '{outputs[i]}'")

    # Create sets of characters
    in_chars = set(inputs[i])
    out_chars = set(outputs[i])

    print(f"  In chars: {sorted(in_chars)}")
    print(f"  Out chars: {sorted(out_chars)}")

    # See what's added
    added = out_chars - in_chars
    if added:
        print(f"  Added chars: {sorted(added)}")

    # See what's removed
    removed = in_chars - out_chars
    if removed:
        print(f"  Removed chars: {sorted(removed)}")

    print()

# Look specifically at repeated patterns
print("Looking for repeated patterns...")
patterns = {}
for i in range(len(inputs)):
    out = outputs[i]
    # Look for common substrings that might represent replacements
    if len(out) > 3:
        # Extract potential replacement patterns
        for length in range(1, min(4, len(out)+1)):
            for start in range(len(out) - length + 1):
                pattern = out[start:start+length]
                if pattern not in patterns:
                    patterns[pattern] = []
                patterns[pattern].append((inputs[i], outputs[i]))

# Check for simple single character replacements
print("\nChecking for single character replacements:")
single_replacements = {}

# Try to find what single characters map to what
for i in range(len(inputs)):
    in_str = inputs[i]
    out_str = outputs[i]

    # Compare character by character
    min_len = min(len(in_str), len(out_str))
    for j in range(min_len):
        if in_str[j] != out_str[j]:
            if in_str[j] not in single_replacements:
                single_replacements[in_str[j]] = out_str[j]
            elif single_replacements[in_str[j]] != out_str[j]:
                print(f"Conflict: {in_str[j]} maps to both {single_replacements[in_str[j]]} and {out_str[j]}")

print("Single char replacements found:", single_replacements)

# Check for multi-character patterns
print("\nChecking for multi-character patterns...")
multi_patterns = {}
for i in range(len(inputs)):
    in_str = inputs[i]
    out_str = outputs[i]

    # Look for common substrings
    for length in range(2, min(4, len(in_str)+1)):
        for start in range(len(in_str) - length + 1):
            sub_in = in_str[start:start+length]
            # Find where this appears in output
            for pos in range(len(out_str) - length + 1):
                sub_out = out_str[pos:pos+length]
                if sub_in == sub_out:
                    continue  # Same substring
                # If sub_in doesn't appear in out_str at all, this might be a replacement
                if sub_in not in out_str:
                    if sub_in not in multi_patterns:
                        multi_patterns[sub_in] = sub_out
                    elif multi_patterns[sub_in] != sub_out:
                        print(f"Conflict in multi-pattern: {sub_in} -> {multi_patterns[sub_in]} vs {sub_out}")

print("Multi-char patterns found:", multi_patterns)

